window.QUIZ_BANK['git-github'] = (window.QUIZ_BANK['git-github']||[]).concat([
{"id":3131,"topic":"git-github","difficulty":"beginner","question":"What type of version control system is Git classified as?","options":["Centralized version control system","Distributed version control system","Lock-based version control system","Linear version control system"],"answer":1,"explanation":"Git is a distributed version control system (DVCS), meaning every developer has a complete local copy of the entire repository history. Unlike centralized systems such as SVN, there is no single required server — any clone can act as a full backup and all operations like commit and log work offline."},
{"id":3132,"topic":"git-github","difficulty":"beginner","question":"What does a Git repository contain?","options":["Only the latest version of source files","Only commit messages and author names","The complete history of all commits, branches, tags, and tracked file changes","Only binary snapshots of a project at specific points in time"],"answer":2,"explanation":"A Git repository stores the complete history of a project including every commit, branch pointer, tag, configuration, and the object database that contains compressed snapshots of tracked files. The repository data is stored in the hidden .git directory at the root of a project."},
{"id":3133,"topic":"git-github","difficulty":"beginner","question":"What is the Git 'working directory' (also called the working tree)?","options":["The remote server where repositories are hosted","The hidden .git folder that contains repository metadata","The local file system view of a single checkout of the project files you can read and edit","The staging area where changes are accumulated before committing"],"answer":2,"explanation":"The working directory (or working tree) is the checkout of one version of the project files onto your local disk. It is the place where you view and edit files. Changes made here are not yet tracked by Git until they are staged with git add or committed directly."},
{"id":3134,"topic":"git-github","difficulty":"beginner","question":"What is the Git staging area (also known as the index)?","options":["A cloud buffer that temporarily holds pushed commits","The final storage location for committed changes","An intermediate area that holds a snapshot of what will go into your next commit","The remote tracking branch that mirrors the upstream repository"],"answer":2,"explanation":"The staging area, also called the index, is a preparatory layer between the working directory and the repository. You explicitly add changes to it with 'git add', allowing you to craft commits selectively — only staged changes are included in the next 'git commit'."},
{"id":3135,"topic":"git-github","difficulty":"beginner","question":"Which command initializes a new empty Git repository in the current directory?","options":["git start","git create","git init","git new"],"answer":2,"explanation":"'git init' creates a new hidden .git directory in the current directory, initializing an empty repository. All repository metadata, object storage, refs, and configuration are stored inside this .git directory from that point forward."},
{"id":3136,"topic":"git-github","difficulty":"beginner","question":"Which command creates a local copy of an existing remote Git repository?","options":["git pull","git fetch","git download","git clone"],"answer":3,"explanation":"'git clone <url>' creates a complete local copy of a remote repository, including its full history, all branches, and all tags. It also sets up the 'origin' remote pointing to the source URL and checks out the default branch automatically."},
{"id":3137,"topic":"git-github","difficulty":"beginner","question":"Which command stages changes in a file so they are included in the next commit?","options":["git stage","git track","git add","git commit -a"],"answer":2,"explanation":"'git add <file>' stages the specified file's changes to the index. You can stage all changes with 'git add .' or all modifications with 'git add -u'. Only staged changes appear in the next commit; unstaged modifications remain in the working directory."},
{"id":3138,"topic":"git-github","difficulty":"beginner","question":"Which command records staged changes as a new commit in the repository history?","options":["git save","git record","git push","git commit"],"answer":3,"explanation":"'git commit' creates a new commit object in the repository that stores a snapshot of all currently staged changes, along with a commit message, author, timestamp, and a pointer to the parent commit. The -m flag allows providing the message inline."},
{"id":3139,"topic":"git-github","difficulty":"beginner","question":"What does 'git status' display?","options":["The full diff of all changes between commits","The list of all remote repositories","The current branch, staged changes, unstaged changes, and untracked files","The complete log of all past commits"],"answer":2,"explanation":"'git status' shows the state of the working directory and the staging area. It reports which branch you are on, which changes are staged for the next commit, which tracked files have unstaged modifications, and which files are completely untracked by Git."},
{"id":3140,"topic":"git-github","difficulty":"beginner","question":"What does 'git log' display by default?","options":["A real-time stream of incoming commits from the remote","The list of all tracked and untracked files in the repository","A reverse-chronological list of commits with hash, author, date, and message","Only the diff of the most recent commit"],"answer":2,"explanation":"'git log' displays the commit history for the current branch in reverse chronological order (newest first). Each entry shows the full SHA-1 hash, author name and email, commit date, and the commit message. Options like --oneline, --graph, and --all customize the output."},
{"id":3141,"topic":"git-github","difficulty":"intermediate","question":"Which 'git log' option displays a compact one-line-per-commit view showing abbreviated hash and subject?","options":["git log --compact","git log --short","git log --oneline","git log --brief"],"answer":2,"explanation":"'git log --oneline' formats each commit as a single line containing only the abbreviated (7-character) commit hash followed by the first line of the commit message. This is extremely useful for getting a quick overview of recent history without the verbose default format."},
{"id":3142,"topic":"git-github","difficulty":"intermediate","question":"What does 'git diff' show when run with no arguments?","options":["Differences between the last two commits","Differences between staged changes and the last commit","Differences between the working directory and the staging area (unstaged changes)","Differences between the local branch and the remote tracking branch"],"answer":2,"explanation":"'git diff' with no arguments shows the changes in tracked files that have been modified but not yet staged. To see staged changes (what would go into the next commit), use 'git diff --staged' or 'git diff --cached'. To compare commits, supply commit references."},
{"id":3143,"topic":"git-github","difficulty":"intermediate","question":"What does 'git diff --staged' (or 'git diff --cached') compare?","options":["The remote branch versus the local branch","The working tree versus the last commit","The staging area (index) versus the last commit (HEAD)","Two arbitrary branches specified by name"],"answer":2,"explanation":"'git diff --staged' (synonymous with --cached) compares what is currently in the staging area against the last commit (HEAD). This lets you preview exactly what changes will be included in the next commit before actually running git commit."},
{"id":3144,"topic":"git-github","difficulty":"intermediate","question":"What does 'git show <commit>' display?","options":["A live stream of the repository's network activity","Only the commit metadata without any diff","The commit metadata (author, date, message) combined with the diff introduced by that commit","All commits that have the same author as the specified commit"],"answer":2,"explanation":"'git show <commit>' displays the commit object information (hash, author, date, message) along with the unified diff of changes introduced by that specific commit compared to its parent. It can also show other object types such as tags, trees, and blobs."},
{"id":3145,"topic":"git-github","difficulty":"beginner","question":"Which command sets your global Git username for all repositories on your machine?","options":["git config user.name 'Name'","git config --global user.name 'Name'","git set --global name 'Name'","git identity --name 'Name'"],"answer":1,"explanation":"'git config --global user.name' writes the specified name to the global Git configuration file (~/.gitconfig). This name is embedded in every commit you make across all repositories on your machine. Omitting --global sets it only for the current repository."},
{"id":3146,"topic":"git-github","difficulty":"beginner","question":"Where does the --global Git configuration get stored?","options":["In the .git/config file of the current repository","In /etc/gitconfig on the system","In the ~/.gitconfig file in the user's home directory","In the /usr/share/git/config file"],"answer":2,"explanation":"The --global Git configuration is stored in the .gitconfig file located in the user's home directory (~/.gitconfig on Unix/macOS, %USERPROFILE%\\.gitconfig on Windows). It applies to all repositories for the current user, overriding system-level settings but being overridden by repository-level settings."},
{"id":3147,"topic":"git-github","difficulty":"intermediate","question":"Which command adds a new remote named 'origin' pointing to a specific URL?","options":["git remote set-url origin <url>","git remote add origin <url>","git link origin <url>","git push --set-upstream origin <url>"],"answer":1,"explanation":"'git remote add <name> <url>' registers a new remote alias in .git/config mapping the name to the URL. By convention 'origin' is the primary remote name. You can add multiple remotes with different names to push or pull from different locations."},
{"id":3148,"topic":"git-github","difficulty":"intermediate","question":"What does 'git fetch origin' do?","options":["Downloads all remote branches and tags updating remote-tracking refs but does NOT modify the working tree or current branch","Automatically merges the remote branch into the current local branch","Deletes local branches that no longer exist on the remote","Uploads local commits to the remote repository"],"answer":0,"explanation":"'git fetch origin' contacts the remote and downloads any new commits, branches, and tags, updating remote-tracking references like origin/main. Critically, it does NOT automatically merge or modify your working tree or local branches — you review fetched changes before integrating them."},
{"id":3149,"topic":"git-github","difficulty":"beginner","question":"What does 'git pull' do?","options":["Uploads local commits to the remote repository","Downloads remote changes and automatically integrates them into the current local branch (fetch + merge)","Deletes the local copy of the remote branch","Shows what changes exist on the remote without downloading them"],"answer":1,"explanation":"'git pull' is shorthand for 'git fetch' followed by 'git merge' (or 'git rebase' with --rebase). It downloads new commits from the tracked remote branch and automatically merges them into your current local branch, updating your working directory."},
{"id":3150,"topic":"git-github","difficulty":"beginner","question":"Which command uploads local commits to a remote repository?","options":["git send","git upload","git push","git sync"],"answer":2,"explanation":"'git push <remote> <branch>' transmits local commits and objects to the specified remote repository and updates its branch references. If the remote branch doesn't exist yet, you can create it with 'git push -u origin <branch>', which also sets the upstream tracking relationship."},
{"id":3151,"topic":"git-github","difficulty":"beginner","question":"Which command lists all local branches in a Git repository?","options":["git branches","git list","git branch","git show-branches"],"answer":2,"explanation":"'git branch' with no arguments lists all local branches, marking the currently checked-out branch with an asterisk (*). Use 'git branch -a' to include remote-tracking branches, or 'git branch -r' to show only remote-tracking branches."},
{"id":3152,"topic":"git-github","difficulty":"beginner","question":"Which command creates a new branch called 'feature/login'?","options":["git new feature/login","git branch feature/login","git create feature/login","git checkout feature/login"],"answer":1,"explanation":"'git branch <name>' creates a new branch pointing at the current HEAD commit without switching to it. To create AND switch in one step, use 'git checkout -b <name>' or the modern 'git switch -c <name>'. Branch names can include slashes for organizational grouping."},
{"id":3153,"topic":"git-github","difficulty":"beginner","question":"What is the purpose of 'git checkout <branch>'?","options":["Creates a new branch with the specified name","Deletes the specified branch from the repository","Switches the working directory to the specified branch, updating tracked files to match that branch's HEAD","Merges the specified branch into the current branch"],"answer":2,"explanation":"'git checkout <branch>' switches your working directory to the specified branch by updating the HEAD pointer and restoring tracked files to match that branch's latest commit. Modern Git (v2.23+) introduced 'git switch <branch>' as a clearer alternative specifically for branch switching."},
{"id":3154,"topic":"git-github","difficulty":"intermediate","question":"What is the modern Git command (introduced in v2.23) recommended for switching branches?","options":["git change","git checkout","git switch","git move"],"answer":2,"explanation":"'git switch' was introduced in Git 2.23 as a dedicated, user-friendly command for switching branches, splitting off the branch-switching functionality from the overloaded 'git checkout' command. Use 'git switch <branch>' to switch, 'git switch -c <name>' to create and switch."},
{"id":3155,"topic":"git-github","difficulty":"intermediate","question":"What is a fast-forward merge in Git?","options":["A merge that resolves all conflicts automatically","A merge where the current branch tip is simply moved forward to the target branch commit because no divergent history exists","A merge that always creates a new merge commit regardless of history","A merge that discards all commit history and creates a single new commit"],"answer":1,"explanation":"A fast-forward merge occurs when the current branch has no new commits diverging from the branch being merged — it is strictly behind the target branch. Git simply advances the current branch pointer to the tip of the target branch without creating a merge commit, resulting in a linear history."},
{"id":3156,"topic":"git-github","difficulty":"intermediate","question":"When does Git perform a 3-way merge instead of a fast-forward merge?","options":["When the --3way flag is explicitly passed","When both branches have diverged with commits not present in the other, requiring a common ancestor to reconcile differences","When the branches share no common commit ancestor at all","When merging between different Git versions"],"answer":1,"explanation":"A 3-way merge is used when both the current branch and the branch being merged have commits not present in the other — they have diverged from a common ancestor. Git uses three snapshots (common ancestor, current branch tip, target branch tip) to compute and apply the combined changes, creating a new merge commit."},
{"id":3157,"topic":"git-github","difficulty":"intermediate","question":"What happens when a merge conflict occurs in Git?","options":["Git automatically selects the newer file version and completes the merge","Git aborts the merge and resets all files to the pre-merge state","Git pauses the merge, marks conflicting sections in affected files with conflict markers, and waits for manual resolution before committing","Git sends an alert to the remote repository owner to resolve the conflict"],"answer":2,"explanation":"When Git detects conflicting changes during a merge, it pauses the operation and inserts conflict markers (<<<<<<<, =======, >>>>>>>) into the affected files. The developer must manually edit the files to resolve the conflicts, then stage the resolved files with 'git add' and complete the merge with 'git commit'."},
{"id":3158,"topic":"git-github","difficulty":"intermediate","question":"What do the conflict markers in a conflicted file represent?","options":["<<<<<<< shows the remote version only; ======= shows the final resolved version","<<<<<<< HEAD through ======= shows the current branch changes; ======= through >>>>>>> shows the incoming branch changes","<<<<<<< marks deleted lines; >>>>>>> marks newly added lines","The markers show syntax errors introduced during the merge"],"answer":1,"explanation":"Git conflict markers delineate the two conflicting versions: the section from '<<<<<<< HEAD' to '=======' contains the changes from your current branch (HEAD), while the section from '=======' to '>>>>>>> <branch>' contains the changes from the branch being merged. You resolve by editing the file to keep the correct content."},
{"id":3159,"topic":"git-github","difficulty":"intermediate","question":"What does 'git rebase <branch>' do?","options":["Creates a new branch off the specified branch","Merges the specified branch into the current branch creating a merge commit","Replays the commits of the current branch on top of the tip of the specified branch, producing a linear history","Deletes commits from the specified branch and reapplies them elsewhere"],"answer":2,"explanation":"'git rebase <branch>' takes commits from the current branch that diverged from the base and re-applies them one by one on top of the specified branch's tip. This rewrites commit history to produce a clean linear history without merge commits, but should only be used on local/private branches."},
{"id":3160,"topic":"git-github","difficulty":"intermediate","question":"What is the golden rule of rebasing in Git?","options":["Always rebase instead of merging to keep history clean","Never rebase commits that have already been pushed to a shared public branch","Always use interactive rebase for local commits","Rebase should only be performed on the main branch"],"answer":1,"explanation":"The golden rule of rebasing is never rebase commits that exist on a shared public branch. Because rebasing rewrites commit hashes, if other developers have based their work on those commits, rebasing forces them into a confusing divergence. Only rebase commits that are purely local and not yet shared."},
{"id":3161,"topic":"git-github","difficulty":"intermediate","question":"What does 'git stash' do?","options":["Permanently deletes uncommitted changes from the working directory","Commits all changes with an auto-generated message","Temporarily saves uncommitted changes (staged and unstaged) to a stack so the working directory is clean","Archives the repository into a compressed ZIP file"],"answer":2,"explanation":"'git stash' saves your current uncommitted modifications (both staged and unstaged tracked changes) to a stash stack and reverts the working directory to a clean state matching HEAD. This is useful when you need to switch context quickly. Use 'git stash pop' or 'git stash apply' to restore the changes later."},
{"id":3162,"topic":"git-github","difficulty":"intermediate","question":"How do you apply the most recent stash entry and remove it from the stash stack?","options":["git stash apply","git stash drop","git stash pop","git stash restore"],"answer":2,"explanation":"'git stash pop' applies the most recently stashed changes back to the working directory and removes that entry from the stash stack. 'git stash apply' applies without removing. 'git stash list' shows all entries and you can reference them by index, e.g., 'git stash pop stash@{2}'."},
{"id":3163,"topic":"git-github","difficulty":"beginner","question":"What is the purpose of the .gitignore file?","options":["It lists all files that have been deleted from the repository","It specifies patterns for files and directories that Git should not track or commit","It lists all contributors and their email addresses","It defines merge conflict resolution rules for specific files"],"answer":1,"explanation":"The .gitignore file contains patterns that tell Git which files and directories to ignore — meaning they will not be tracked, staged, or committed. Common entries include build artifacts (target/, dist/), dependency folders (node_modules/), IDE settings (.idea/), and environment files (.env)."},
{"id":3164,"topic":"git-github","difficulty":"intermediate","question":"In a .gitignore file, what does a pattern starting with a forward slash (/) indicate?","options":["The pattern should be applied recursively in all subdirectories","The pattern is anchored to the root of the repository and only matches at that level","The pattern is a regex rather than a glob pattern","The pattern applies only to binary files"],"answer":1,"explanation":"A pattern starting with '/' in .gitignore anchors the match to the root of the repository directory. For example, '/build' matches only a 'build' directory at the project root, not 'src/build'. Without the leading slash, the pattern matches at any depth in the directory tree."},
{"id":3165,"topic":"git-github","difficulty":"intermediate","question":"How do you ignore all .log files in any directory using .gitignore?","options":["*.log only at the root","**/*.log","log/","*.log"],"answer":3,"explanation":"The pattern '*.log' in .gitignore matches all files with the .log extension in any directory throughout the repository tree because a pattern without a slash is matched relative to every directory. '**/*.log' is also valid but redundant — '*.log' already applies recursively by default."},
{"id":3166,"topic":"git-github","difficulty":"intermediate","question":"How can you negate (un-ignore) a previously ignored pattern in .gitignore?","options":["By placing the pattern on a line marked with // (double slash)","By prefixing the pattern with ! to explicitly include it","By adding an except: keyword before the pattern","By creating a .gitallow file with the un-ignored patterns"],"answer":1,"explanation":"Prefixing a pattern with '!' negates it, meaning files matching this pattern will NOT be ignored even if a previous rule matched them. For example, '*.log' then '!important.log' ignores all .log files except important.log. Note: you cannot un-ignore a file inside an ignored directory."},
{"id":3167,"topic":"git-github","difficulty":"intermediate","question":"What does 'git clean -fd' do?","options":["Removes staged changes from the index without touching working files","Deletes all untracked files and directories from the working tree","Cleans up stale remote-tracking branches","Removes all local branches that have been merged"],"answer":1,"explanation":"'git clean -fd' forcibly removes untracked files (-f for force) and untracked directories (-d) from the working tree. This is irreversible — those files are not moved to the trash. Use 'git clean -nfd' first for a dry run to preview what would be deleted before committing to the operation."},
{"id":3168,"topic":"git-github","difficulty":"intermediate","question":"What does 'git remote -v' display?","options":["The version of the Git client installed","A verbose list of all configured remote names along with their fetch and push URLs","The list of branches on the remote repository","The network latency to the remote server"],"answer":1,"explanation":"'git remote -v' (verbose) lists each configured remote alias along with its fetch URL and push URL. By default these are the same URL, but they can be configured separately. This is useful for verifying remote configurations, especially when working with forks or multiple remotes."},
{"id":3169,"topic":"git-github","difficulty":"intermediate","question":"What is a Git tag, and how does it differ from a branch?","options":["A tag and a branch are identical — both are movable pointers to commits","A tag is a static, named reference to a specific commit that does not move as new commits are added, unlike a branch pointer which moves forward","A tag stores a diff while a branch stores full snapshots","A tag is only available in remote repositories whereas branches are local"],"answer":1,"explanation":"A Git tag is a named reference permanently pointing to a specific commit, typically used to mark release versions. Unlike a branch pointer that automatically advances with new commits, a tag is immutable once created. Annotated tags (git tag -a) store additional metadata and are signed objects; lightweight tags are simple pointers."},
{"id":3170,"topic":"git-github","difficulty":"beginner","question":"Which command creates an annotated Git tag named 'v1.0.0' with a message?","options":["git tag v1.0.0","git tag -l v1.0.0 'Release'","git tag -a v1.0.0 -m 'Release 1.0.0'","git tag --create v1.0.0 'Release 1.0.0'"],"answer":2,"explanation":"'git tag -a <name> -m <message>' creates an annotated tag, which is a full Git object storing the tagger name, date, message, and optionally a GPG signature. Annotated tags are preferred over lightweight tags for release versions because they contain this extra metadata and can be cryptographically signed."},
{"id":3171,"topic":"git-github","difficulty":"intermediate","question":"How do you push all local tags to the remote repository?","options":["git push --all","git push origin --tags","git push origin tags","git push --include-tags"],"answer":1,"explanation":"'git push origin --tags' pushes all local tags that do not yet exist on the remote. By default, 'git push' does not transmit tags. To push a single specific tag, use 'git push origin <tagname>'. Deleting a remote tag requires 'git push origin --delete <tagname>'."},
{"id":3172,"topic":"git-github","difficulty":"intermediate","question":"What does 'git commit --amend' do?","options":["Creates a completely new commit independent of the last commit","Modifies the most recent commit by replacing it with a new commit incorporating staged changes and/or an updated message","Appends additional commits to the branch without altering history","Reverts the last commit and stages the changes again"],"answer":1,"explanation":"'git commit --amend' replaces the last commit with a new one that includes any currently staged changes combined with the previous commit's changes. It also lets you edit the commit message. Because this rewrites the last commit (new hash), avoid amending commits already pushed to a shared repository."},
{"id":3173,"topic":"git-github","difficulty":"intermediate","question":"What is 'git rebase -i HEAD~3' used for?","options":["Resets the last 3 commits, discarding all changes","Launches an interactive rebase editor letting you edit, squash, reorder, or drop the last 3 commits","Fetches the 3 most recent commits from the remote","Creates 3 new branches from the last 3 commits"],"answer":1,"explanation":"'git rebase -i HEAD~3' opens an interactive rebase editor for the last 3 commits. You can reorder them, squash them into fewer commits (squash/fixup), edit their messages (reword), pause to edit changes (edit), or delete them (drop). This is a powerful tool for cleaning up local commit history before pushing."},
{"id":3174,"topic":"git-github","difficulty":"intermediate","question":"What does squashing commits mean in the context of interactive rebase?","options":["Deleting all commits in a range permanently from history","Combining multiple consecutive commits into a single commit","Splitting a single commit into multiple smaller commits","Moving commits from one branch to another"],"answer":1,"explanation":"Squashing in interactive rebase (using 'squash' or 'fixup' commands) combines the marked commit with the commit directly above it, merging their changes into one. This is commonly used to clean up a feature branch's work-in-progress commits into a single coherent commit before merging into the main branch."},
{"id":3175,"topic":"git-github","difficulty":"intermediate","question":"What does 'git branch -d <branch>' do?","options":["Forcibly deletes the branch regardless of whether changes are merged","Deletes the branch only if all its commits have been merged into the current branch","Detaches the branch from its upstream tracking reference","Renames the branch to a deleted state"],"answer":1,"explanation":"'git branch -d <branch>' safely deletes a local branch only if all its commits are reachable from the current branch (i.e., already merged). If unmerged work exists, Git refuses and suggests using 'git branch -D <branch>' (capital D) to forcibly delete regardless of merge status."},
{"id":3176,"topic":"git-github","difficulty":"intermediate","question":"What does 'git checkout -b <branch>' do as a single command?","options":["Checks out an existing branch and creates a backup of it","Creates a new branch AND switches to it in a single step","Creates a branch on the remote without switching locally","Creates a new branch from the remote tracking reference"],"answer":1,"explanation":"'git checkout -b <name>' is shorthand for 'git branch <name>' followed by 'git checkout <name>' — it creates a new branch pointing at current HEAD and immediately switches to it. The equivalent modern command is 'git switch -c <name>'."},
{"id":3177,"topic":"git-github","difficulty":"advanced","question":"What is a detached HEAD state in Git?","options":["The HEAD points to a branch that has been deleted","HEAD points directly to a commit hash rather than to a named branch reference","The HEAD file is missing from the .git directory","HEAD is pointing to a stash entry"],"answer":1,"explanation":"A detached HEAD state occurs when HEAD points directly to a commit SHA rather than to a symbolic branch reference. This happens when you checkout a specific commit, tag, or remote tracking branch. New commits can be made but will be orphaned (not on any branch) unless you create a branch to capture them."},
{"id":3178,"topic":"git-github","difficulty":"intermediate","question":"How do you configure 'git pull' to use rebase instead of merge?","options":["git pull --mode=rebase","git pull --rebase","git pull -m rebase","git fetch && git rebase only"],"answer":1,"explanation":"'git pull --rebase' performs a fetch and then rebases your local commits on top of the fetched remote commits instead of merging. You can set this as the default behavior globally with 'git config --global pull.rebase true', which keeps a cleaner linear history compared to merge-based pulls."},
{"id":3179,"topic":"git-github","difficulty":"intermediate","question":"What does 'git merge --no-ff <branch>' ensure?","options":["The merge is performed without any file conflicts","Even when a fast-forward is possible, a merge commit is always created to explicitly record the merge","The merge is aborted if the target branch has diverged","All commits from the source branch are squashed into one before merging"],"answer":1,"explanation":"'git merge --no-ff' (no fast-forward) forces creation of a merge commit even when Git could simply fast-forward the pointer. This preserves the historical context that a feature branch existed and groups all its commits visually in the history, which many teams prefer for traceability in GitFlow workflows."},
{"id":3180,"topic":"git-github","difficulty":"intermediate","question":"What does 'git merge --squash <branch>' do?","options":["Performs a fast-forward merge from the branch","Merges all commits from the branch into one single commit staged in the index but does NOT automatically create the merge commit","Creates a squash-merge commit that records the complete branch history","Deletes the source branch after merging"],"answer":1,"explanation":"'git merge --squash <branch>' stages all changes from the source branch as a single set of staged modifications in the index, but does NOT automatically commit. You then run 'git commit' to create a single clean commit. This condenses the entire feature branch's history into one commit on the target branch."},
{"id":3181,"topic":"git-github","difficulty":"intermediate","question":"What is the purpose of 'git fetch --prune'?","options":["Deletes all local untracked files as part of the fetch","Fetches remote changes and removes stale remote-tracking references for branches deleted on the remote","Prunes the Git object database by garbage collecting unreachable objects","Removes all local tags not present on the remote"],"answer":1,"explanation":"'git fetch --prune' first fetches any new changes from the remote and then removes local remote-tracking references (like origin/feature-x) that no longer exist on the remote server. This keeps your local view of remote branches synchronized and avoids confusion from stale branch references."},
{"id":3182,"topic":"git-github","difficulty":"intermediate","question":"How do you rename a local Git branch from 'old-name' to 'new-name'?","options":["git branch --rename old-name new-name","git branch -m old-name new-name","git mv branch old-name new-name","git checkout --rename old-name new-name"],"answer":1,"explanation":"'git branch -m <old-name> <new-name>' renames an existing local branch. If you are already on the branch you want to rename, you can simply run 'git branch -m <new-name>'. After renaming, you'll need to delete the old remote branch and push the new name if it was already pushed."},
{"id":3183,"topic":"git-github","difficulty":"intermediate","question":"What does 'git log --graph --oneline --all' show?","options":["Only the log of the currently checked-out branch in one line","An ASCII art graph of all branches and their commit relationships in compact one-line format","The diff graph for all uncommitted changes","The network bandwidth usage graph for remote operations"],"answer":1,"explanation":"'git log --graph --oneline --all' combines three useful flags: --graph draws ASCII art branch lines showing merge and branch structure, --oneline compacts each commit to one line with abbreviated hash and message, and --all includes all refs (branches, tags, remotes) rather than just the current branch."},
{"id":3184,"topic":"git-github","difficulty":"intermediate","question":"How do you undo the last commit but keep the changes staged (ready to recommit)?","options":["git reset --hard HEAD~1","git reset --soft HEAD~1","git revert HEAD","git checkout HEAD~1"],"answer":1,"explanation":"'git reset --soft HEAD~1' moves the branch pointer back one commit but preserves all the changes from that commit in the staging area (index). The working directory files are unchanged. This lets you adjust the commit's content or message and recommit without losing any work."},
{"id":3185,"topic":"git-github","difficulty":"intermediate","question":"What is the difference between 'git reset --mixed' and 'git reset --soft'?","options":["--mixed is more aggressive and deletes files from disk; --soft does not","--mixed moves branch pointer back and unstages changes (changes remain in working directory); --soft moves pointer back but keeps changes staged","--mixed only affects remote refs while --soft only affects local refs","--soft always merges while --mixed always rebases"],"answer":1,"explanation":"'git reset --soft' moves the branch pointer to the specified commit and keeps changes staged in the index. 'git reset --mixed' (the default) moves the pointer AND unstages changes, placing them in the working directory as modified but unstaged. Neither mode deletes changes from the working directory."},
{"id":3186,"topic":"git-github","difficulty":"advanced","question":"What does 'git reset --hard HEAD~1' do?","options":["Stages the changes from the last commit for modification","Moves the branch pointer back one commit and discards all changes from the working directory and index permanently","Resets only the index while keeping the working tree intact","Creates an undo commit that reverses the last commit"],"answer":1,"explanation":"'git reset --hard HEAD~1' moves both the branch pointer and the index AND the working directory back to the state of the previous commit, permanently discarding all changes from the last commit. This is destructive and should be used with caution — use 'git reflog' to recover if needed."},
{"id":3187,"topic":"git-github","difficulty":"intermediate","question":"What does 'git diff HEAD' show?","options":["The diff between HEAD and the remote branch","All changes since the very first commit","All changes in the working directory and index compared to the last commit (HEAD)","The diff between HEAD and HEAD~1"],"answer":2,"explanation":"'git diff HEAD' shows all differences between the current working state (both staged and unstaged changes) and the last commit (HEAD). This is a convenient way to see everything that has changed since the last commit, regardless of whether changes are staged or not."},
{"id":3188,"topic":"git-github","difficulty":"intermediate","question":"Which command shows which commit a specific line of a file was last modified in and by whom?","options":["git trace","git history","git blame","git annotate"],"answer":2,"explanation":"'git blame <file>' annotates each line of a file with the commit hash, author, and timestamp of when that line was last changed. This is invaluable for understanding the context behind code changes and identifying who introduced a specific line. 'git annotate' is a similar but deprecated alias."},
{"id":3189,"topic":"git-github","difficulty":"intermediate","question":"How do you list all stash entries currently saved?","options":["git stash view","git stash list","git stash show --all","git stash index"],"answer":1,"explanation":"'git stash list' shows all entries in the stash stack with their stash reference (stash@{0}, stash@{1}, ...), the branch they were created on, and the commit message at the time of stashing. The most recent stash is stash@{0}."},
{"id":3190,"topic":"git-github","difficulty":"advanced","question":"What is the '--force-with-lease' option used for when pushing to a remote?","options":["Forces a push even if remote tracking info is outdated, but only if no one else has pushed since you last fetched","Forces a push unconditionally, overwriting any remote changes","Pushes using a lease-based signed certificate for authentication","Limits the push to lease-only protected branches"],"answer":0,"explanation":"'git push --force-with-lease' is a safer alternative to 'git push --force'. It allows overwriting the remote branch only if your local remote-tracking ref matches the remote's current state — meaning it fails if someone else has pushed new commits since your last fetch, preventing accidental data loss."},
{"id":3191,"topic":"git-github","difficulty":"intermediate","question":"What does 'git log --follow <file>' do differently from regular 'git log'?","options":["Shows commits only from the current author for a file","Tracks renames and shows the history of a file even across renames","Follows merge commits into their parent branches","Shows log in real-time as new commits arrive"],"answer":1,"explanation":"'git log --follow <file>' traces the history of a file across renames and moves. Without --follow, 'git log <file>' stops at rename boundaries. Using --follow, Git detects similarity-based rename history and continues showing commits even when the file was moved or renamed at some point."},
{"id":3192,"topic":"git-github","difficulty":"intermediate","question":"What does 'git shortlog -sn' produce?","options":["A summary of all short commit messages sorted by date","A count of commits per author sorted by number of contributions","A short log of all branches and their last commit","A list of all tags sorted numerically"],"answer":1,"explanation":"'git shortlog -sn' produces a summary (-s) sorted by count (-n) showing each author and their number of commits. This is a quick way to see contribution statistics. 'git shortlog' without options groups commits by author with their messages listed under each name."},
{"id":3193,"topic":"git-github","difficulty":"intermediate","question":"How do you see the content of a specific file as it existed in a previous commit without checking out that commit?","options":["git diff <commit> -- <file>","git show <commit>:<file>","git log --file <commit> <file>","git cat-file <commit>/<file>"],"answer":1,"explanation":"'git show <commit>:<file>' prints the content of the specified file as it existed at the given commit, without changing your working directory or HEAD. This is useful for inspecting historical versions of files while staying on the current branch."},
{"id":3194,"topic":"git-github","difficulty":"advanced","question":"What is the purpose of 'git gc' (garbage collection)?","options":["Removes all .gitignore patterns and resets them to default","Compresses loose objects, removes unreachable objects, and optimizes the repository's on-disk storage","Cleans all untracked files from the working directory","Garbage collects stale remote-tracking branches not present on the remote"],"answer":1,"explanation":"'git gc' runs Git's garbage collection mechanism. It packs loose objects into pack files, removes objects unreachable from any reference (after their grace period), and runs other housekeeping tasks like repacking and pruning. Large repositories benefit significantly from periodic garbage collection."},
{"id":3195,"topic":"git-github","difficulty":"intermediate","question":"What does the git configuration option 'core.autocrlf' control?","options":["Whether Git automatically resolves merge conflicts","How Git handles line-ending conversions between Windows CRLF and Unix LF on checkout and commit","The maximum line length allowed in commit messages","Whether Git automatically creates branches for remote refs"],"answer":1,"explanation":"'core.autocrlf' controls automatic line-ending normalization. Setting it to 'true' (Windows) converts LF to CRLF on checkout and CRLF to LF on commit. 'input' (Linux/macOS) only converts CRLF to LF on commit. 'false' disables conversion. Proper configuration prevents spurious cross-platform diffs."},
{"id":3196,"topic":"git-github","difficulty":"intermediate","question":"How do you set a custom global Git commit message editor (e.g., VS Code)?","options":["git config --global editor vscode","git config --global core.editor 'code --wait'","git config --global commit.editor 'vscode --wait'","git env set EDITOR vscode"],"answer":1,"explanation":"'git config --global core.editor' sets the editor Git opens for commit messages, interactive rebases, and similar operations. The '--wait' flag is essential for GUI editors — it tells the shell to wait until the editor window is closed before Git proceeds, preventing Git from reading an empty file."},
{"id":3197,"topic":"git-github","difficulty":"intermediate","question":"What does 'git log --since=\"2 weeks ago\" --author=\"Alice\"' filter?","options":["Shows Alice's pending pull requests from the past 2 weeks","Shows commits authored by Alice in the last 2 weeks","Shows all commits that mention Alice in the message within 2 weeks","Shows commits reviewed by Alice in the last 2 weeks"],"answer":1,"explanation":"'git log' supports rich filtering. '--since' (or '--after') limits commits to those newer than the specified date/time expression, and '--author' filters by author name or email. Combined, this command lists all commits made by Alice in the last two weeks on the current branch."},
{"id":3198,"topic":"git-github","difficulty":"advanced","question":"What is the Git object model? Which four types of objects does Git store?","options":["Files, directories, remotes, and branches","Blob, Tree, Commit, and Tag objects","Snapshot, Delta, Index, and Pack objects","Stage, Unstage, Push, and Pull objects"],"answer":1,"explanation":"Git's object model consists of four immutable object types stored by content-addressable SHA-1 hash: Blob (file content), Tree (directory listing mapping names to blobs/trees), Commit (snapshot pointer with metadata and parent links), and Tag (annotated tag object). All of Git's operations are manipulations of these four object types."},
{"id":3199,"topic":"git-github","difficulty":"intermediate","question":"What does 'git log -p' (or '--patch') show?","options":["Shows only the patch version of Git","Displays the commit log along with the complete diff introduced by each commit","Shows only commits that modified or patched a specified file","Produces a git format-patch output for emailing"],"answer":1,"explanation":"'git log -p' or 'git log --patch' extends the standard commit log to include the full unified diff (patch) that each commit introduced. This is useful for understanding not just which commits exist but exactly what code changes each commit made, combining log and diff in one output."},
{"id":3200,"topic":"git-github","difficulty":"intermediate","question":"Which command verifies the integrity of a Git repository by checking that all objects are reachable and not corrupted?","options":["git verify","git health","git fsck","git check-integrity"],"answer":2,"explanation":"'git fsck' (file system check) traverses all reachable objects in the repository and checks their consistency and connectivity. It reports dangling objects (unreachable but not garbage collected yet), missing objects, and any corruption. Running 'git fsck' is a good diagnostic step when investigating repository issues."},
{"id":3201,"topic":"git-github","difficulty":"intermediate","question":"How do you apply a .patch file created with 'git format-patch' to a repository?","options":["git patch apply <file.patch>","git am <file.patch>","git diff --apply <file.patch>","git import <file.patch>"],"answer":1,"explanation":"'git am' (apply mailbox) applies a series of patch files created with 'git format-patch'. Unlike 'git apply', 'git am' preserves the original commit metadata (author, date, message) and creates proper commits. It is commonly used for email-based patch workflows."},
{"id":3202,"topic":"git-github","difficulty":"intermediate","question":"What does 'git log --grep=\"bug fix\"' do?","options":["Searches the content of tracked files for 'bug fix'","Filters the commit log to only show commits whose message contains the string 'bug fix'","Searches for branches named 'bug fix'","Finds all commits that were reverted with message 'bug fix'"],"answer":1,"explanation":"'git log --grep=<pattern>' filters the commit log to show only commits whose commit message matches the specified regular expression pattern. This is useful for finding commits related to specific features, bug numbers, or keywords. Combine with --all-match to require multiple --grep patterns to all match."},
{"id":3203,"topic":"git-github","difficulty":"intermediate","question":"What is 'git log -S <string>' (the pickaxe option) used for?","options":["Searches commit messages for the string","Finds commits that introduced or removed a specific string in the file content (code search)","Shows statistics about how many times a string appears","Searches branch names for the given string"],"answer":1,"explanation":"'git log -S <string>' (the pickaxe) searches through the actual code changes to find commits where the specified string was added or removed. This is extremely useful for tracking when a specific function name, variable, or code pattern was introduced or deleted, regardless of commit messages."},
{"id":3204,"topic":"git-github","difficulty":"advanced","question":"What does 'git bisect' do?","options":["Splits a single large commit into two smaller commits","Uses binary search through the commit history to efficiently find the commit that introduced a regression or bug","Bisects a branch into two parallel branches","Compares two branches and shows the bisected difference"],"answer":1,"explanation":"'git bisect' implements a binary search algorithm to find the commit that introduced a bug. You mark a good (known-working) commit and a bad (broken) commit, then Git checks out the midpoint. You mark it good or bad, and Git narrows the range until the culprit commit is identified, typically in O(log n) steps."},
{"id":3205,"topic":"git-github","difficulty":"intermediate","question":"What is the correct sequence to start a git bisect session?","options":["git bisect find, then git bisect start","git bisect start, then git bisect bad <commit>, then git bisect good <commit>","git bisect begin, then mark commits, then git bisect end","git bisect run <script> and let it find automatically"],"answer":1,"explanation":"To use git bisect: first 'git bisect start', then 'git bisect bad' (current commit is broken), then 'git bisect good <commit>' (known-working older commit). Git checks out the midpoint commit for you to test. After marking each as good or bad, Git homes in on the first bad commit."},
{"id":3206,"topic":"git-github","difficulty":"intermediate","question":"What happens when you run 'git push -u origin main'?","options":["Pushes only tags to the remote","Pushes the main branch to origin and sets it as the upstream tracking branch for future git push/pull without arguments","Forcefully overwrites the remote main branch","Creates a pull request on the remote platform"],"answer":1,"explanation":"'git push -u origin main' pushes the local main branch to the remote 'origin' AND sets the upstream tracking configuration with -u (--set-upstream). After this, you can simply run 'git push' or 'git pull' without specifying the remote and branch — Git already knows where to push/pull."},
{"id":3207,"topic":"git-github","difficulty":"intermediate","question":"What does the 'git remote set-url' command do?","options":["Creates a new remote alias","Changes the URL associated with an existing remote","Lists all URLs for all remotes","Tests connectivity to the remote URL"],"answer":1,"explanation":"'git remote set-url <name> <newurl>' updates the URL stored for an existing remote in .git/config. This is commonly used when migrating a repository to a new host (e.g., from GitHub to GitLab), when switching between HTTPS and SSH authentication, or when a repository is renamed on the remote platform."},
{"id":3208,"topic":"git-github","difficulty":"intermediate","question":"What is a 'detached HEAD' scenario you would encounter when using git bisect?","options":["Git bisect never creates a detached HEAD","git bisect checks out individual commits during the binary search, intentionally creating detached HEAD states","A detached HEAD in bisect means the session has failed","The HEAD is always attached to the bisect branch during the process"],"answer":1,"explanation":"During 'git bisect', Git checks out individual commits that are not at the tip of any branch to allow testing of that specific state. This intentionally creates a detached HEAD. Once 'git bisect reset' is run, HEAD is reattached to the original branch."},
{"id":3209,"topic":"git-github","difficulty":"advanced","question":"What is a Git packfile and why is it important?","options":["A ZIP archive created by git archive","A binary file that stores many Git objects in compressed delta-compressed format, crucial for network transfer efficiency and disk space optimization","A configuration bundle for sharing .gitconfig settings","A format for bundling multiple repositories together"],"answer":1,"explanation":"Git packfiles (.pack files in .git/objects/pack/) store many objects in a delta-compressed format, where similar objects are stored as deltas relative to each other rather than full copies. This dramatically reduces repository size. Packfiles are created during 'git gc', 'git repack', and during clone/fetch operations."},
{"id":3210,"topic":"git-github","difficulty":"intermediate","question":"What does 'git config --list' do?","options":["Lists all available git commands","Shows all currently effective configuration key-value pairs from system, global, and local levels","Lists all Git repositories on the system","Shows the diff of configuration changes made recently"],"answer":1,"explanation":"'git config --list' displays all configuration settings currently in effect, merging system (/etc/gitconfig), global (~/.gitconfig), and local (.git/config) configurations. Keys from lower-priority levels are overridden by higher-priority local settings. Add --show-origin to see which config file each setting comes from."},
{"id":3211,"topic":"git-github","difficulty":"intermediate","question":"What does 'git archive --format=tar.gz HEAD > project.tar.gz' do?","options":["Creates a Git bundle of the full repository","Exports the current HEAD snapshot of tracked files into a tar.gz archive without including the .git directory","Backs up all repository objects into a compressed archive","Creates a ZIP of all staged files only"],"answer":1,"explanation":"'git archive' creates an archive (tar, tar.gz, zip) of a specific tree-ish (branch, tag, or commit) containing only the tracked file contents — no .git metadata. This is ideal for creating clean source distributions or deployment packages without exposing repository history."},
{"id":3212,"topic":"git-github","difficulty":"advanced","question":"What is 'git worktree' and what problem does it solve?","options":["A feature for managing multiple .gitignore worktrees","A command that allows checking out multiple branches simultaneously in separate directories from a single repository","A tool for managing Git submodule workspaces","An alias for the working directory in Git documentation"],"answer":1,"explanation":"'git worktree add <path> <branch>' creates an additional working tree linked to the same repository, checking out a different branch in a separate directory. This solves the problem of needing to switch branches when you have uncommitted work — instead, you work on two branches in two directories simultaneously without stashing."},
{"id":3213,"topic":"git-github","difficulty":"intermediate","question":"What does 'git stash branch <branchname>' do?","options":["Creates a branch and then immediately stashes the current changes onto it","Creates a new branch from the commit at which the stash was made, applies the stash, and drops it","Pushes the stash to a remote branch for collaborative review","Renames a stash entry to the specified branch name"],"answer":1,"explanation":"'git stash branch <name>' creates a new branch starting at the commit where the stash was created, checks it out, then applies the stash and drops it if successful. This is a clean way to convert stashed work into a proper feature branch when you realize the work deserves its own branch."},
{"id":3214,"topic":"git-github","difficulty":"intermediate","question":"What does the --depth flag in 'git clone --depth=1' create?","options":["Clones only the first level of directories","Creates a shallow clone with only the most recent commit and truncated history to reduce clone time and disk space","Clones only to the first merge point in history","Clones the repository without any tags or branches"],"answer":1,"explanation":"'git clone --depth=1' creates a shallow clone that includes only the most recent commit rather than the full history. This significantly speeds up clone time and reduces disk usage, making it popular in CI/CD pipelines where full history is unnecessary. You can deepen later with 'git fetch --deepen=<n>'."},
{"id":3215,"topic":"git-github","difficulty":"intermediate","question":"What is the significance of the HEAD~1 notation in Git?","options":["HEAD~1 always refers to the main branch","HEAD~1 refers to the first parent of HEAD, i.e., the commit one step back in the ancestry chain","HEAD~1 is an alias for the stash stack top","HEAD~1 refers to the last tag before HEAD"],"answer":1,"explanation":"HEAD~1 (or HEAD~) means 'the first parent of HEAD', navigating one step back in the commit ancestry. HEAD~2 goes two steps back, etc. For merge commits with multiple parents, HEAD^1 and HEAD^2 select specific parents (first/second), while HEAD~2 always follows the first-parent chain."},
{"id":3216,"topic":"git-github","difficulty":"intermediate","question":"What does 'git push origin :feature/old-branch' do (note the colon before the branch name)?","options":["Creates a new branch called ':feature/old-branch' on the remote","Deletes the 'feature/old-branch' branch from the remote repository","Pushes an empty commit to the remote branch","Renames the remote branch to an unnamed ref"],"answer":1,"explanation":"The syntax 'git push origin :<branch>' (colon followed by branch name) deletes the specified branch on the remote. It's the refspec syntax meaning 'push nothing to this ref', effectively deleting it. The modern equivalent is 'git push origin --delete feature/old-branch', which is more readable."},
{"id":3217,"topic":"git-github","difficulty":"intermediate","question":"How does 'git log --merges' filter the commit log?","options":["Shows only merge commits (commits with more than one parent)","Shows only commits that contain the word 'merge' in their message","Shows the history of merges from the remote only","Shows only squash-merged commits"],"answer":0,"explanation":"'git log --merges' shows only commits that are merge commits — commits that have two or more parents. This is useful for auditing when and which branches were merged. The opposite, 'git log --no-merges', excludes merge commits and shows only direct work commits."},
{"id":3218,"topic":"git-github","difficulty":"intermediate","question":"What file in the .git directory stores the SHA-1 of the currently checked-out commit or branch reference?","options":["COMMIT_EDITMSG","ORIG_HEAD","HEAD","FETCH_HEAD"],"answer":2,"explanation":"The .git/HEAD file is a special pointer file that contains either a symbolic reference to the current branch (e.g., 'ref: refs/heads/main') or a direct SHA-1 hash in detached HEAD mode. Git consults HEAD to know what the current position in history is for operations like commit and log."},
{"id":3219,"topic":"git-github","difficulty":"intermediate","question":"What is 'ORIG_HEAD' in Git?","options":["The original first commit in the repository","A reference automatically saved by Git to the previous HEAD position before operations that significantly move it (like merge, rebase, or reset)","The HEAD of the original upstream repository before forking","The first parent of the current HEAD commit"],"answer":1,"explanation":"ORIG_HEAD is a special reference Git writes before performing operations that move HEAD significantly, such as merge, rebase, reset, or checkout. If the operation has undesired effects, you can use 'git reset --hard ORIG_HEAD' to return to the pre-operation state quickly."},
{"id":3220,"topic":"git-github","difficulty":"intermediate","question":"What happens to commits that become unreachable after a 'git reset --hard'?","options":["They are immediately and permanently deleted from the repository","They remain in the Git object database as dangling objects and are accessible via git reflog until garbage collected","They are automatically moved to a backup branch","They remain on the remote repository unchanged"],"answer":1,"explanation":"When commits become unreachable (no branch or tag points to them), they are not immediately deleted. Git retains them as dangling objects in the object database. They remain visible in 'git reflog' for a configurable period (default 90 days) before 'git gc' prunes them, providing a recovery window."},
{"id":3221,"topic":"git-github","difficulty":"intermediate","question":"What is the purpose of 'git notes'?","options":["A note-taking app integrated into the Git GUI","A mechanism to attach arbitrary text annotations to commits without altering the commit hash","A way to add inline comments to source code through Git","A feature for storing code review comments locally"],"answer":1,"explanation":"'git notes' allows adding extra annotations to commits that are stored as separate objects and don't alter the original commit hash. Notes are useful for adding post-hoc metadata like code review feedback, build results, or deployment information. They are stored in refs/notes/commits by default."},
{"id":3222,"topic":"git-github","difficulty":"beginner","question":"What does .gitignore pattern 'build/' (with trailing slash) match?","options":["Any file or directory named build anywhere in the repository","Only a file named build at the repository root","Only a directory named build (and its contents) anywhere in the repository tree","Any path containing the word build"],"answer":2,"explanation":"A pattern ending with a forward slash '/' in .gitignore instructs Git to match only directories with that name, not files. So 'build/' matches directories named 'build' and ignores all of their contents recursively, but does not match a regular file named 'build'."},
{"id":3223,"topic":"git-github","difficulty":"intermediate","question":"How do you tell Git to stop tracking a file that is already tracked (remove it from tracking without deleting it from disk)?","options":["git remove --keep <file>","git rm --cached <file>","git untrack <file>","git ignore <file>"],"answer":1,"explanation":"'git rm --cached <file>' removes the file from the Git index (stops tracking it) without deleting the physical file from disk. After running this, you should add the file's pattern to .gitignore to prevent it from appearing as untracked. This is commonly needed for files like .env accidentally committed."},
{"id":3224,"topic":"git-github","difficulty":"intermediate","question":"What command can be used to see all commits that are in branch-A but NOT in branch-B?","options":["git log branch-A..branch-B","git log branch-B..branch-A","git diff branch-A branch-B","git compare branch-B branch-A"],"answer":1,"explanation":"The double-dot syntax 'git log branch-B..branch-A' shows commits that are reachable from branch-A but not from branch-B. This is the standard way to see what commits a feature branch has that main does not yet have, i.e., what would be added by a merge from branch-A into branch-B."},
{"id":3225,"topic":"git-github","difficulty":"advanced","question":"What does the triple-dot syntax 'git log branch-A...branch-B' show?","options":["All commits reachable from branch-A but not branch-B","Commits reachable from either branch-A or branch-B but NOT from their common ancestor (symmetric difference)","All commits on both branches combined","The diff between the tips of both branches"],"answer":1,"explanation":"The triple-dot syntax computes the symmetric difference — commits reachable from branch-A OR branch-B but not from their common ancestor. This shows what has diverged on both sides since the branches split. 'git diff branch-A...branch-B' shows what was changed on branch-B since it diverged from branch-A."},
{"id":3226,"topic":"git-github","difficulty":"intermediate","question":"What does 'git clean -n' do?","options":["No-operation: simply validates the .gitignore file","Dry run: shows what files WOULD be deleted by git clean without actually deleting anything","Cleans only empty directories","Removes files from the index but not the filesystem"],"answer":1,"explanation":"'git clean -n' (or --dry-run) is a safe preview mode that lists the untracked files that WOULD be deleted if you ran 'git clean -f', without actually deleting anything. Always run a dry run before 'git clean -f' or 'git clean -fd' to avoid accidentally deleting needed files."},
{"id":3227,"topic":"git-github","difficulty":"intermediate","question":"How do you configure a global .gitignore file that applies to all repositories on your system?","options":["Place a .gitignore file in /etc/git/","git config --global ignore.file ~/.gitignore_global","git config --global core.excludesFile ~/.gitignore_global","There is no way to have a global .gitignore"],"answer":2,"explanation":"'git config --global core.excludesFile <path>' sets a global gitignore file applied to every repository on the system. This is useful for ignoring OS files (e.g., .DS_Store on macOS, Thumbs.db on Windows) and IDE configurations (.idea/, .vscode/) without adding them to every project's .gitignore."},
{"id":3228,"topic":"git-github","difficulty":"intermediate","question":"What is the effect of 'git commit -a'?","options":["Commits all files including untracked files","Stages all modifications and deletions to already-tracked files and commits them in one step, bypassing manual git add","Commits with an automatically generated commit message","Commits only files that were staged with git add"],"answer":1,"explanation":"'git commit -a' (or --all) automatically stages all changes to tracked files (modifications and deletions) before committing — it is equivalent to 'git add -u && git commit'. Crucially, it does NOT stage new untracked files; those must be explicitly added with 'git add' first."},
{"id":3229,"topic":"git-github","difficulty":"advanced","question":"What is the 'refspec' in Git?","options":["A reference specification used in git push/fetch to map local refs to remote refs","A file specification format for .gitignore patterns","The specification format for commit messages","A reference to the git specification standard document"],"answer":0,"explanation":"A refspec is a mapping pattern in the form '<src>:<dest>' that specifies how local refs map to remote refs (or vice versa) during push or fetch operations. For example, 'refs/heads/main:refs/heads/main' maps the local main branch to the remote main branch. Refspecs are stored in .git/config under remote entries."},
{"id":3230,"topic":"git-github","difficulty":"intermediate","question":"How do you checkout a specific file from a different branch without switching branches?","options":["git fetch <branch> -- <file>","git checkout <branch> -- <file>","git pull <branch> -- <file>","git copy <branch>/<file>"],"answer":1,"explanation":"'git checkout <branch> -- <file>' retrieves the specified file content from the given branch or commit and places it in the current working directory and staging area, without switching the entire branch. This is useful for cherry-picking individual files from other branches or restoring accidentally deleted files."},
{"id":3231,"topic":"git-github","difficulty":"intermediate","question":"What does 'git restore <file>' do (Git 2.23+)?","options":["Restores the file to its version at the last tag","Discards uncommitted changes in the working directory, restoring the file to its staged or HEAD version","Restores a deleted branch","Restores a deleted tag"],"answer":1,"explanation":"'git restore <file>' (introduced in Git 2.23) discards changes in the working directory for the specified file, restoring it to its state in the staging area (or HEAD if unstaged). It replaces the confusing 'git checkout -- <file>' syntax with a more explicit, dedicated command for restoring files."},
{"id":3232,"topic":"git-github","difficulty":"intermediate","question":"What does 'git restore --staged <file>' do?","options":["Restores the staged file to the remote version","Unstages the file (removes it from the index) while keeping the working directory changes intact","Permanently removes the file from tracking","Moves the staged file to a stash"],"answer":1,"explanation":"'git restore --staged <file>' removes the file from the staging area (index) and puts its changes back as unstaged modifications in the working directory. This is the modern replacement for 'git reset HEAD <file>' to unstage files."},
{"id":3233,"topic":"git-github","difficulty":"advanced","question":"What is the difference between a Git lightweight tag and an annotated tag?","options":["Lightweight tags can be pushed to remotes while annotated tags cannot","A lightweight tag is just a named pointer to a commit with no extra data; an annotated tag is a full Git object with tagger, date, message, and optional GPG signature","Lightweight tags store diffs while annotated tags store full snapshots","Annotated tags expire after 90 days while lightweight tags are permanent"],"answer":1,"explanation":"A lightweight tag ('git tag <name>') is simply a named reference file pointing directly to a commit — no extra object is created. An annotated tag ('git tag -a <name> -m <msg>') creates a tag object in the database containing the tagger's identity, a timestamp, a message, and optionally a GPG signature. Annotated tags are recommended for releases."},
{"id":3234,"topic":"git-github","difficulty":"intermediate","question":"How do you delete a local Git branch?","options":["git branch --remove <name>","git remove branch <name>","git branch -d <name>","git delete branch <name>"],"answer":2,"explanation":"'git branch -d <name>' deletes a local branch safely (only if merged). 'git branch -D <name>' force-deletes regardless of merge status. You cannot delete the branch you are currently on — switch to a different branch first. Deleting a local branch does not affect any corresponding remote branch."},
{"id":3235,"topic":"git-github","difficulty":"intermediate","question":"What does 'git log --stat' add to the standard log output?","options":["Statistical analysis of code quality per commit","Each commit entry shows which files changed and the number of insertions/deletions per file","Only shows commits that changed more than a statistically significant amount","Shows execution statistics for each git log call"],"answer":1,"explanation":"'git log --stat' appends to each commit entry a summary of which files were modified, and how many lines were added (+) and deleted (-) in each file, plus a totals summary. This provides a quick overview of the scope of changes per commit without showing the full diff."},
{"id":3236,"topic":"git-github","difficulty":"advanced","question":"What does 'git stash -u' (or --include-untracked) do differently from plain 'git stash'?","options":["Stashes only unstaged tracked changes","Stashes uncommitted changes AND also includes untracked (new) files that haven't been git-added yet","Stashes only files modified more than 24 hours ago","Stashes changes with an auto-generated unique identifier"],"answer":1,"explanation":"Plain 'git stash' only saves changes to tracked files (modified and staged). 'git stash -u' also saves untracked files (new files not yet added to the index). 'git stash -a' (--all) goes further by also including files ignored by .gitignore."},
{"id":3237,"topic":"git-github","difficulty":"intermediate","question":"What is a 'bare' Git repository?","options":["A repository with no commits yet","A repository that contains only the .git directory contents (no working tree), used as a centralized shared repository on servers","A repository with all files untracked","A repository missing its configuration file"],"answer":1,"explanation":"A bare repository ('git init --bare' or 'git clone --bare') contains only the repository data (object database, refs, config) without a working tree. Remote hosting services like GitHub effectively serve bare repositories. You cannot do development directly in a bare repo — it is only for sharing and pushing/pulling."},
{"id":3238,"topic":"git-github","difficulty":"advanced","question":"How does Git calculate a commit's SHA-1 hash?","options":["It is a random UUID assigned at commit time","It is calculated from the hash of the commit object's content including tree reference, parent hash, author, committer, message, and timestamp","It is a sequential integer incremented for each commit","It is a hash of only the changed file contents"],"answer":1,"explanation":"Git computes the SHA-1 hash of the commit object's content: tree hash (full snapshot), parent commit hash(es), author name/email/timestamp, committer name/email/timestamp, and commit message. This makes each commit cryptographically dependent on its full history — any change to any ancestor changes all descendant hashes."},
{"id":3239,"topic":"git-github","difficulty":"intermediate","question":"What does 'git log --decorate' add to the output?","options":["Adds festive color schemes to the terminal output","Shows ref names (branch names, tags, HEAD) next to the commits they point to","Adds the GPG signature status of each commit","Adds the file tree decorated as an ASCII art diagram"],"answer":1,"explanation":"'git log --decorate' (enabled by default in many environments) annotates commit entries with the names of refs that point to them — branch names, tag names, HEAD, and remote-tracking branches. This gives immediate visual context about which commits are branch tips or release points."},
{"id":3240,"topic":"git-github","difficulty":"intermediate","question":"What is the purpose of 'git config core.hooksPath'?","options":["Sets the path where Git downloads hook scripts from a remote","Changes the directory where Git looks for hook scripts, enabling team-shared hooks stored in the repository","Sets the execution path for the git binary","Configures the path for storing configuration backups"],"answer":1,"explanation":"'git config core.hooksPath <path>' (Git 2.9+) tells Git to look for hook scripts in a custom directory instead of the default .git/hooks/. Setting this to a directory tracked in the repository (e.g., '.githooks') allows teams to share and version-control their git hooks, which was previously impossible since .git/ is not tracked."},
]);
